questions.push(
  question("BIO_R4_Q_S115_01", "BIO_R4_S115", "foundation", 0, "剪下植物莖段插入介質並促使生根，屬於哪種方法？", ["扦插", "授粉", "嫁接", "種子播種"], ["切離營養器官直接生根成株符合扦插。", "授粉是花粉到柱頭，並非莖段生根。", "嫁接需把接穗接到砧木，不只插入介質。", "題目使用莖段而不是受精後形成的種子。"], ["辨認重點是材料已切離母株並直接生根，與仍連母株的壓條不同。", "扦插屬無性繁殖，可較快保存母株既有品種性狀。"], ["扦插"], "情境", ["扦插等於嫁接"]),
  question("BIO_R4_Q_S115_02", "BIO_R4_S115", "foundation", 1, "枝條仍連母株時先促使生根，之後再切離，稱為什麼？", ["組織培養", "壓條", "種子繁殖", "人工授粉"], ["組織培養使用小塊組織與無菌培養條件。", "先連母株生根再切離是壓條的特徵。", "種子繁殖需經有性生殖形成種子。", "人工授粉處理的是花粉到柱頭。"], ["壓條在生根初期保留與母株連接，可降低枝條立即缺水的風險。", "切離時點是辨認壓條與扦插的重要證據，不能只看最後都有根。"], ["壓條"], "情境", ["壓條先切離"]),
  question("BIO_R4_Q_S115_03", "BIO_R4_S115", "foundation", 2, "嫁接中提供根系與下部支撐的部分稱為什麼？", ["接穗", "花粉", "砧木", "胚珠"], ["接穗通常是希望保留地上部性狀的枝或芽。", "花粉是有性生殖構造，不是嫁接根系。", "砧木位於下部並提供根系與支撐。", "胚珠位在花的子房內，受精後形成種子。"], ["嫁接辨認要同時記住接穗在上、砧木在下，以及兩者各自提供的功能。", "砧木抗病不代表接穗細胞遺傳資訊被改寫，兩部分來源仍不同。"], ["砧木"], "文字", ["砧木與接穗顛倒"]),
  question("BIO_R4_Q_S115_04", "BIO_R4_S115", "standard", 3, "組織培養能由少量材料快速繁殖，最需要注意哪項條件？", ["讓培養基暴露於各種微生物", "完全不提供水與養分", "每次都加入不同物種花粉", "材料與器具消毒並維持適當無菌環境"], ["微生物會利用培養基並污染植物組織。", "培養組織需要適當水分與養分才能生長。", "組織培養不以花粉受精作為必要步驟。", "無菌控制可降低細菌與真菌競爭及感染。"], ["培養基同時適合許多微生物生長，因此污染控制是大量繁殖能否成功的關鍵。", "無菌不代表缺少空氣或養分，仍須提供植物組織適合的生長條件。"], ["組織培養"], "方法", ["培養不需無菌"]),
  question("BIO_R4_Q_S115_05", "BIO_R4_S115", "standard", 0, "農民要快速保存優良葡萄品種的果實性狀，哪項做法較合適？", ["選健康母株進行扦插並監測病害", "混合多品種花粉後隨機播種", "只收集落葉而不促使再生", "移除所有可生長的芽"], ["健康莖段扦插可快速形成與母株性狀相近新株。", "有性繁殖會增加後代組合，不利維持高度一致。", "落葉若無再生能力不能達成繁殖目標。", "移除生長點會降低新株形成機會。"], ["保存既有品種重視性狀穩定，適合使用可行的營養繁殖並從健康母株取材。", "大量相近植株也可能共享病害弱點，因此健康檢測不可因無性繁殖而省略。"], ["品種保存"], "農業", ["有性繁殖保持完全一致"]),
  question("BIO_R4_Q_S115_06", "BIO_R4_S115", "standard", 1, "果樹嫁接時，若要保留特定果實性狀，應如何選擇材料？", ["只選砧木葉片而不接枝", "以該品種枝芽作接穗，接到合適砧木", "把兩株種子混在同一土壤", "移除接穗後只保留傷口"], ["只留砧木不能保留指定接穗果實性狀。", "接穗形成新梢，可延續所選品種的地上部性狀。", "混種不會建立嫁接的組織連接。", "移除接穗就失去希望保留的枝芽來源。"], ["嫁接用途來自兩部分功能搭配，接穗保留品種，砧木提供適合根系。", "還須確認兩者親和且形成層接合良好，否則外觀看似固定也未必成功。"], ["嫁接選材"], "應用", ["砧木決定全部果實性狀"]),
  question("BIO_R4_Q_S115_07", "BIO_R4_S115", "standard", 2, "下列哪項最能區分扦插與嫁接？", ["兩者都可能需要澆水", "兩者最後都可能形成葉片", "扦插材料自行生根，嫁接接穗依附砧木根系", "兩者都必須先形成種子"], ["澆水是共同栽培條件，不能區分方法。", "形成葉片也可能是兩種方法共同結果。", "根系來源與是否結合兩株材料是核心差異。", "兩者都是營養繁殖，不必先經種子。"], ["辨認方法應看操作材料與連接關係，而不是後來都會生長的共同現象。", "扦插成功需要切段生根，嫁接成功則需要接穗與砧木組織癒合。"], ["方法比較"], "概念", ["共同結果當區分依據"]),
  question("BIO_R4_Q_S115_08", "BIO_R4_S115", "advanced", 3, "嫁接後接穗結果、砧木提供抗病根系，最恰當的解釋為何？", ["兩部分所有細胞融合成相同遺傳組成", "砧木會把果實直接運到接穗", "接穗已變成砧木的種子", "兩部分保持來源差異，藉組織連通互補功能"], ["癒合不等於所有細胞遺傳資訊完全混合。", "砧木供水與礦物質，不會製成果實再運送。", "接穗是枝芽組織，不會轉成砧木種子。", "共同生長可同時利用上部品種與下部根系特點。"], ["嫁接是一株外觀下的兩個來源組織合作，不是有性生殖式的遺傳重組。", "判斷果實性狀仍以接穗新梢為主，但砧木可間接影響生長勢與環境適應。"], ["嫁接原理"], "推論", ["嫁接等於遺傳融合"]),
  question("BIO_R4_Q_S115_09", "BIO_R4_S115", "advanced", 0, "大量無性繁殖香蕉遇新病原時，為何可能同時受害？", ["植株遺傳相近，可能共享對病原的易感性", "每株都由不同配子組合形成", "無性繁殖會讓病原完全消失", "營養繁殖後植物不再具有細胞"], ["相近遺傳背景可能使抗病反應也相近。", "無性繁殖通常不是每株由不同配子形成。", "繁殖方式本身不會消滅環境中的病原。", "新株仍由許多正常植物細胞構成。"], ["保存一致性是農業優點，也可能把相同弱點複製到大片作物。", "降低風險可結合健康種苗、病害監測、環境管理與多樣品系。"], ["病害風險"], "農業推論", ["性狀一致保證抗病"]),
  question("BIO_R4_Q_S115_10", "BIO_R4_S115", "advanced", 1, "比較壓條與扦插成活率時，哪項設計最公平？", ["壓條用幼枝，扦插用老根且環境不同", "同品種相近枝條分組，控制季節與環境並記錄生根成活", "只記錄成功案例，不計失敗材料", "壓條組澆水，扦插組完全乾燥"], ["材料年齡與器官不同會混入額外差異。", "相近材料和環境能比較是否保留母株連接的影響。", "排除失敗會高估成活率並造成偏差。", "水分不同使結果無法歸因於繁殖方法。"], ["公平比較要讓主要差異是枝條生根時是否仍連母株，並使用足夠重複。", "成活率分母須包含所有處理材料，不能只展示成功植株。"], ["方法實驗"], "探究", ["選擇性回報"]),
  question("BIO_R4_Q_S115_11", "BIO_R4_S115", "transfer", 2, "稀有植物僅剩少量健康芽，需快速增殖，哪項方案最合理？", ["等待未知昆蟲隨機授粉", "把所有芽放在污染土壤", "以無菌組織培養增殖並保留部分原株", "先移除芽的生長組織"], ["隨機授粉速度與後代性狀都較難控制。", "污染環境可能使珍貴材料感染死亡。", "少量芽可在控制環境擴增，保留原株也分散風險。", "移除生長組織會破壞可用培養材料。"], ["材料極少時不宜一次耗盡，組織培養與原株保留可兼顧增殖和風險管理。", "培養後仍須確認遺傳與健康狀態，避免污染或培養變異擴大。"], ["保育應用"], "策略", ["珍稀材料全部投入單一處理"]),
  question("BIO_R4_Q_S115_12", "BIO_R4_S115", "transfer", 3, "報導稱「嫁接能把兩品種融合成全新有性後代」，應如何修正？", ["正確，組織癒合就是配子融合", "正確，接穗會變成受精卵", "錯誤，嫁接後兩部分完全不能交換物質", "嫁接是營養繁殖的組織接合，不等同配子融合形成後代"], ["組織癒合與精卵配子融合是不同層級事件。", "接穗保持枝芽組織，不會轉變成受精卵。", "接合成功後可運輸水分與養分，並非完全隔絕。", "修正保留嫁接合作功能並區分有性生殖。"], ["嫁接可形成共同生長的植株外觀，但不會因此把兩者每個細胞的遺傳資訊混成一套。", "若要產生有性後代，仍需花粉與卵細胞融合並由受精卵發育。"], ["媒體評析"], "新情境", ["嫁接等於受精"]),
);

